import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Jubilacion = () => {
  const [data, setData] = useState([]);
  const [predictions, setPredictions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  useEffect(() => {
    // Hacer la solicitud a la API para los datos
    const fetchData = async () => {
      try {
        const response = await axios.get('https://api.fastforex.io/time-series', {
          params: {
            from: 'USD',
            to: 'EUR',
            interval: 'P1D',
            api_key: 'c80584cb38-3c1fd2f449-sk8eb7'
          }
        });
        
        const dataJson = response.data;
        const timeSeries = dataJson.results.EUR;

        // Convertir datos a formato para recharts
        const formattedData = Object.keys(timeSeries).map(date => ({
          fecha: date,
          valor: timeSeries[date]
        }));
        
        setData(formattedData);
        
        // Solicitar predicciones
        const predResponse = await axios.get('http://localhost:5000/api/predicciones'); // Cambia la URL según tu configuración
        setPredictions(predResponse.data);
        
        setLoading(false);
      } catch (error) {
        setError('Error al cargar los datos.');
        setLoading(false);
      }
    };
    
    fetchData();
  }, []);
  
  if (loading) return <p>Cargando...</p>;
  if (error) return <p>{error}</p>;

  // Combinar datos históricos y predicciones
  const combinedData = [...data, ...predictions];

  return (
    <div>
      <h2>Predicción de Tipo de Cambio USD/EUR para Jubilación</h2>
      <ResponsiveContainer width="100%" height={400}>
        <LineChart data={combinedData}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="fecha" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="valor" stroke="#8884d8" activeDot={{ r: 8 }} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Jubilacion;
